/* Rutledge-style decayed reward model; experimental everyday-life adaptation. */
(function(root){
'use strict';
const clip=x=>Math.max(0,Math.min(10,x));
function valid(e){return e&&['certain','uncertain'].includes(e.kind)&&['expected','reward','happiness'].every(k=>Number.isFinite(e[k])&&e[k]>=0&&e[k]<=10)}
function step(memory,e,gamma){const event=e.kind==='certain'?[e.reward,0,0]:[0,e.expected,e.reward-e.expected];return memory.map((v,k)=>gamma*v+event[k])}
function features(events,gamma){let memory=[0,0,0];return events.map(e=>{memory=step(memory,e,gamma);return [1,...memory]})}
function solve(a,b){const n=b.length,m=a.map((row,i)=>[...row,b[i]]);for(let j=0;j<n;j++){let p=j;for(let i=j+1;i<n;i++)if(Math.abs(m[i][j])>Math.abs(m[p][j]))p=i;[m[p],m[j]]=[m[j],m[p]];if(Math.abs(m[j][j])<1e-10)return null;const scale=m[j][j];for(let k=j;k<=n;k++)m[j][k]/=scale;for(let i=0;i<n;i++)if(i!==j){const c=m[i][j];for(let k=j;k<=n;k++)m[i][k]-=c*m[j][k]}}return m.map(row=>row[n])}
function fit(x,y){const a=Array.from({length:4},()=>[0,0,0,0]),b=[0,0,0,0];x.forEach((row,i)=>{for(let j=0;j<4;j++){b[j]+=row[j]*y[i];for(let k=0;k<4;k++)a[j][k]+=row[j]*row[k]}});for(let j=1;j<4;j++)a[j][j]+=1;return solve(a,b)}
const rawPredict=(beta,x)=>beta.reduce((sum,v,i)=>sum+v*x[i],0);
function chooseGamma(events){let winner={gamma:0,error:Infinity};for(const gamma of [0,.25,.5,.75,.9]){const x=features(events,gamma);let error=0,n=0;for(let i=8;i<events.length;i++){const beta=fit(x.slice(0,i),events.slice(0,i).map(e=>e.happiness));if(!beta)continue;error+=Math.abs(clip(rawPredict(beta,x[i]))-events[i].happiness);n++}if(n&&error/n<winner.error)winner={gamma,error:error/n}}return winner.gamma}
function train(input){const events=input.filter(valid).slice(-200),n=events.length;if(n<24)return {ready:false,n,reason:`${n}/24 observations recorded on this scale. Record ${24-n} more to run a first check.`};const split=Math.floor(n*.7),training=events.slice(0,split),gamma=chooseGamma(training),x=features(events,gamma),betaTrain=fit(x.slice(0,split),training.map(e=>e.happiness));if(!betaTrain)return {ready:false,n,reason:'The observations do not support a stable fit yet.'};const test=events.slice(split),baseline=training.reduce((s,e)=>s+e.happiness,0)/split;let error=0,baseError=0;test.forEach((e,i)=>{error+=Math.abs(clip(rawPredict(betaTrain,x[split+i]))-e.happiness);baseError+=Math.abs(baseline-e.happiness)});const mae=error/test.length,baselineMae=baseError/test.length;const beta=fit(x,events.map(e=>e.happiness)),memory=x[x.length-1].slice(1);return {ready:mae+1e-6<baselineMae,n,gamma,beta,memory,mae,baselineMae,trainN:split,testN:test.length,rewardMin:Math.min(...events.map(e=>e.reward)),rewardMax:Math.max(...events.map(e=>e.reward)),types:[...new Set(events.map(e=>e.kind))],reason:mae+1e-6<baselineMae?'The model beat a fixed training-average baseline on the held-out tail. This is preliminary evidence, not validation for everyday decisions.':'The model has not beaten your training-average baseline on later observations. Predictions are withheld.'}}
function predict(model,event){if(!model.ready||!model.types.includes(event.kind))return null;const memory=step(model.memory,event,model.gamma),raw=rawPredict(model.beta,[1,...memory]);return {value:clip(raw),clipped:raw<0||raw>10,extrapolation:event.reward<model.rewardMin||event.reward>model.rewardMax}}
function demo(){let memory=[0,0,0],seed=531;const next=()=>{seed=(seed*16807)%2147483647;return seed/2147483647};return Array.from({length:48},(_,i)=>{const e={kind:i%3===0?'certain':'uncertain',expected:Math.round(next()*10),reward:Math.round(next()*10)};memory=step(memory,e,.5);return {...e,happiness:clip(4+.06*memory[0]+.09*memory[1]+.24*memory[2]+(next()-.5)*.1),label:'Simulated observation '+(i+1)}})}
const api={valid,step,features,fit,chooseGamma,train,predict,demo,clip};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.MomentaryModel=api;
})(typeof window!=='undefined'?window:globalThis);
